import java.math.BigDecimal;  // We'll need this for accurate money math

public class BankAccountRecord {
    public static void main(String[] args) {

        // ============================================================
        // PART 1: Declare variables with ALL 8 primitive types
        // Use the MOST APPROPRIATE type for each banking field
        // ============================================================

        long   accountNumber  = 9876543210L;    // Long: large numbers need 'L' suffix
        short  branchCode     = 1042;            // Short: branch codes are small numbers
        int    transactionCount = 1_500;         // Int: underscores improve readability!
        byte   kycStatus      = 2;              // Byte: 0=Pending, 1=Submitted, 2=Verified
        double balanceDisplay  = 1_50_000.75;   // Double: default decimal type
        float  interestRate   = 8.5f;           // Float: needs 'f' suffix
        char   accountType    = 'S';            // Char: 'S'=Savings, 'C'=Current
        boolean isActive      = true;           // Boolean: only true or false

        // ============================================================
        // PART 2: Print all fields
        // ============================================================
        System.out.println("========== Bank Account Details ==========");
        System.out.printf("Account Number  : %d%n", accountNumber);
        System.out.printf("Branch Code     : %d%n", branchCode);
        System.out.printf("Transaction Count: %d%n", transactionCount);
        System.out.printf("KYC Status      : %d (0=Pending, 1=Submitted, 2=Verified)%n", kycStatus);
        System.out.printf("Balance         : %.2f%n", balanceDisplay);
        System.out.printf("Interest Rate   : %.1f%%%n", interestRate);
        System.out.printf("Account Type    : %c%n", accountType);
        System.out.printf("Is Active       : %b%n", isActive);

        // ============================================================
        // PART 3: Ranges — run these and understand the results
        // ============================================================
        System.out.println("\n========== Primitive Ranges ==========");
        System.out.println("Byte max     : " + Byte.MAX_VALUE);    // TASK: What is it?
        System.out.println("Short max    : " + Short.MAX_VALUE);   // TASK: What is it?
        System.out.println("Int max      : " + Integer.MAX_VALUE); // TASK: What is it?
        System.out.println("Long max     : " + Long.MAX_VALUE);    // TASK: What is it?

        // ============================================================
        // PART 4: EXPERIMENT — Integer Overflow (DO NOT SKIP!)
        // ============================================================
        System.out.println("\n========== Overflow Experiment ==========");
        int max = Integer.MAX_VALUE;
        System.out.println("Integer.MAX_VALUE     : " + max);
        System.out.println("Integer.MAX_VALUE + 1 : " + (max + 1));  // Unexpected result!
        // TASK: Write a comment here explaining WHY you get this result

        // ============================================================
        // PART 5: Why NOT double for money — the floating-point trap
        // ============================================================
        System.out.println("\n========== Floating-Point Precision ==========");
        double d1 = 0.1 + 0.2;
        System.out.println("0.1 + 0.2 = " + d1);            // Not 0.3!
        System.out.println("== 0.3 ? " + (d1 == 0.3));       // false!

        // The CORRECT way for financial calculations:
        BigDecimal bd1 = new BigDecimal("0.1");
        BigDecimal bd2 = new BigDecimal("0.2");
        BigDecimal bdSum = bd1.add(bd2);
        System.out.println("BigDecimal 0.1+0.2 = " + bdSum);  // Exact: 0.3
        System.out.println("== 0.3 ? " + (bdSum.compareTo(new BigDecimal("0.3")) == 0));
    }
}

public class OperatorsDemo {
    public static void main(String[] args) {

        // ============================================================
        // SECTION 1: Arithmetic Operators
        // ============================================================
        double principal = 500_000.0;  // ₹5 lakh loan
        double annualRate = 0.09;       // 9% per annum (as decimal: 9/100)
        int    years = 3;

        // Simple Interest = P * R * T
        double simpleInterest = principal * annualRate * years;

        // Compound Interest Amount = P * (1 + r)^t
        // Math.pow(base, exponent) computes power
        double compoundAmount = principal * Math.pow(1 + annualRate, years);
        double compoundInterest = compoundAmount - principal;

        System.out.println("===== Interest Calculation =====");
        System.out.printf("Principal     : ₹%.2f%n", principal);
        System.out.printf("Rate          : %.1f%% per annum%n", annualRate * 100);
        System.out.printf("Years         : %d%n", years);
        System.out.printf("Simple Interest   : ₹%.2f%n", simpleInterest);
        System.out.printf("Compound Interest : ₹%.2f%n", compoundInterest);
        System.out.printf("Extra with compound: ₹%.2f%n", compoundInterest - simpleInterest);

        // Modulo operator: practical use
        // Check if a transaction ID is even or odd (used for partitioning in systems)
        int transactionId = 847293;
        System.out.println("\nTransaction ID: " + transactionId);
        System.out.println("Is even? " + (transactionId % 2 == 0));
        System.out.println("Last digit: " + (transactionId % 10));  // Always last digit!

        // ============================================================
        // SECTION 2: Relational and Logical Operators
        // ============================================================
        double balance = 25_000.0;
        double withdrawAmount = 10_000.0;
        boolean isFrozen = false;
        boolean kycVerified = true;
        double minBalance = 1_000.0;

        // Can customer withdraw?
        // Conditions: not frozen, KYC verified, balance after withdrawal >= minBalance
        boolean canWithdraw = !isFrozen 
                           && kycVerified 
                           && (balance - withdrawAmount) >= minBalance;

        System.out.println("\n===== Withdrawal Eligibility =====");
        System.out.println("Balance: ₹" + balance);
        System.out.println("Withdraw: ₹" + withdrawAmount);
        System.out.println("Account frozen: " + isFrozen);
        System.out.println("KYC verified: " + kycVerified);
        System.out.println("Can withdraw? " + canWithdraw);

        // ============================================================
        // SECTION 3: Increment/Decrement
        // ============================================================
        System.out.println("\n===== ATM PIN Attempts =====");
        int attempts = 0;
        System.out.println("Attempt " + (++attempts) + " of 3");  // Pre-increment: shows 1
        System.out.println("Attempt " + (++attempts) + " of 3");  // Pre-increment: shows 2
        System.out.println("Attempt " + (++attempts) + " of 3");  // Pre-increment: shows 3
        // TASK: What would happen if you used attempts++ (post) instead? Try it!

        // ============================================================
        // SECTION 4: Assignment Operators (compound)
        // ============================================================
        System.out.println("\n===== Running Balance =====");
        double runningBalance = 50_000.0;
        System.out.println("Starting balance: ₹" + runningBalance);

        runningBalance += 25_000;  // Deposit 25000: same as runningBalance = runningBalance + 25000
        System.out.println("After deposit ₹25000: ₹" + runningBalance);

        runningBalance -= 10_000;  // Withdrawal
        System.out.println("After withdrawal ₹10000: ₹" + runningBalance);

        runningBalance *= 1.08;    // Apply 8% interest (multiply by 1.08)
        System.out.printf("After 8%% interest: ₹%.2f%n", runningBalance);

        // ============================================================
        // SECTION 5: Ternary Operator
        // ============================================================
        System.out.println("\n===== Account Classification =====");
        double finalBalance = runningBalance;

        String tier = (finalBalance >= 1_00_000) ? "PREMIUM" : "STANDARD";
        String overdraftEligible = (finalBalance >= 50_000) ? "Yes" : "No";

        System.out.printf("Balance: ₹%.2f%n", finalBalance);
        System.out.println("Account Tier: " + tier);
        System.out.println("Overdraft Eligible: " + overdraftEligible);

        // ============================================================
        // CHALLENGE: EMI Calculator
        // Formula: EMI = P * r * (1+r)^n / ((1+r)^n - 1)
        // where P = principal, r = monthly rate, n = months
        // ============================================================
        System.out.println("\n===== EMI Calculator =====");
        double loanAmount = 3_00_000.0;    // ₹3 lakh
        double monthlyRate = 0.09 / 12;    // 9% annual / 12 months
        int months = 24;                    // 2 year loan

        // TODO: Complete the EMI formula:
        // double emi = ???
        // System.out.printf("Monthly EMI: ₹%.2f%n", emi);
        // System.out.printf("Total repayment: ₹%.2f%n", emi * months);
        // System.out.printf("Total interest: ₹%.2f%n", (emi * months) - loanAmount);
    }
}

public class ATMSimulator {

    // Constants — named clearly, UPPER_SNAKE_CASE
    static final int    MAX_PIN_ATTEMPTS      = 3;
    static final double MIN_BALANCE           = 1_000.0;
    static final double MAX_DAILY_WITHDRAWAL  = 50_000.0;
    static final int    CORRECT_PIN           = 1234;     // In real apps, NEVER hardcode PINs!

    public static void main(String[] args) {
        double balance = 25_000.0;
        boolean isAuthenticated = false;
        int attemptCount = 0;

        // ============================================================
        // SECTION 1: PIN Authentication — DO-WHILE loop
        // Runs at least once (show prompt before checking condition)
        // ============================================================
        int[] simulatedPINs = {9999, 5678, 1234};  // Simulates user input: 2 wrong, then correct
        int pinIndex = 0;

        System.out.println("========== Welcome to RoboBank ATM ==========");

        do {
            int enteredPIN = simulatedPINs[pinIndex++];
            attemptCount++;

            if (enteredPIN == CORRECT_PIN) {
                isAuthenticated = true;
                System.out.println("PIN verified. Welcome!");
            } else {
                int remaining = MAX_PIN_ATTEMPTS - attemptCount;
                // TODO: Print a message showing how many attempts remain
                // Example: "Incorrect PIN. 2 attempt(s) remaining."
            }

        } while (!isAuthenticated && attemptCount < MAX_PIN_ATTEMPTS);

        // TODO: If not authenticated after 3 attempts, print card blocked message and return
        // Use: if (!isAuthenticated) { System.out.println(...); return; }

        // ============================================================
        // SECTION 2: Transaction Menu — SWITCH statement
        // ============================================================
        char[] transactions = {'W', 'D', 'W', 'Q', 'W'};  // W=Withdraw, D=Deposit, Q=Quit
        double[] amounts     = {5000, 10000, 30000, 0, 1000};
        double totalWithdrawn = 0;

        System.out.println("\n--- Transaction Processing ---");

        for (int i = 0; i < transactions.length; i++) {
            char txnType = transactions[i];
            double amount  = amounts[i];

            System.out.printf("%nTransaction #%d: Type=%c, Amount=₹%.0f%n", i+1, txnType, amount);

            switch (txnType) {
                case 'W':  // Withdrawal
                    // TODO: Check if amount > MAX_DAILY_WITHDRAWAL
                    //       Check if balance - amount >= MIN_BALANCE (minimum balance rule)
                    //       If OK: deduct from balance, add to totalWithdrawn, print success
                    //       Else: print appropriate error message

                    if (amount > MAX_DAILY_WITHDRAWAL) {
                        System.out.println("  ERROR: Exceeds daily limit of ₹" + MAX_DAILY_WITHDRAWAL);
                    } else if (balance - amount < MIN_BALANCE) {
                        System.out.printf("  ERROR: Insufficient funds. Balance after: ₹%.2f (min ₹%.0f required)%n",
                                          balance - amount, MIN_BALANCE);
                    } else {
                        balance -= amount;
                        totalWithdrawn += amount;
                        System.out.printf("  SUCCESS: Dispensed ₹%.0f. New balance: ₹%.2f%n", amount, balance);
                    }
                    break;

                case 'D':  // Deposit
                    // TODO: Add amount to balance, print success message
                    balance += amount;
                    System.out.printf("  SUCCESS: Deposited ₹%.0f. New balance: ₹%.2f%n", amount, balance);
                    break;

                case 'Q':  // Quit
                    System.out.println("  Ending session. Thank you!");
                    // TODO: Use break to exit the for loop (not just the switch)
                    // Hint: You'll need a labeled break OR refactor with a boolean flag
                    break;

                default:
                    System.out.println("  ERROR: Unknown transaction type: " + txnType);
            }
        }

        // ============================================================
        // SECTION 3: Summary — FOR loop + continue
        // ============================================================
        double[] allTxns = {5000, 10000, -5000, 0, 30000, -2000, 1000};
        // Positive = credit, Negative = debit, 0 = ignore

        System.out.println("\n--- Transaction Summary ---");
        double totalCredit = 0;
        double totalDebit  = 0;

        for (double txn : allTxns) {
            if (txn == 0) continue;  // Skip zero amounts — continue goes to next iteration
            if (txn > 0) {
                totalCredit += txn;
                System.out.printf("  CREDIT: +₹%.2f%n", txn);
            } else {
                totalDebit += Math.abs(txn);  // Math.abs() gives absolute value
                System.out.printf("  DEBIT:  -₹%.2f%n", Math.abs(txn));
            }
        }

        System.out.println("\n===== Session Summary =====");
        System.out.printf("Total Credited : ₹%.2f%n", totalCredit);
        System.out.printf("Total Debited  : ₹%.2f%n", totalDebit);
        System.out.printf("Final Balance  : ₹%.2f%n", balance);
        System.out.printf("PIN Attempts   : %d%n", attemptCount);
    }
}

import java.util.Arrays;

public class BranchDashboard {
    public static void main(String[] args) {

        // ============================================================
        // SECTION 1: Array Creation and Initialization
        // ============================================================
        String[] branches  = {"Mumbai", "Delhi", "Kolkata", "Chennai", "Hyderabad", "Bengaluru"};
        double[] deposits  = {85_00_000, 1_23_00_000, 67_00_000, 92_00_000, 1_11_00_000, 1_05_00_000};
        // deposits in rupees:    85L     1.23Cr     67L        92L         1.11Cr        1.05Cr

        // KEY CONCEPT: arr.length is a FIELD (no parentheses!)
        System.out.println("Number of branches: " + branches.length);
        System.out.println("Deposits array size: " + deposits.length);

        // ============================================================
        // SECTION 2: Traversal with Index (traditional for)
        // Use when you need the index
        // ============================================================
        System.out.println("\n===== Branch Deposits (Raw) =====");
        for (int i = 0; i < branches.length; i++) {
            System.out.printf("%-12s : ₹%,.2f%n", branches[i], deposits[i]);
            // %-12s → left-aligned, padded to 12 chars for clean column alignment
            // %,.2f → number with commas and 2 decimal places
        }

        // ============================================================
        // SECTION 3: Calculations using enhanced for-each
        // Use when you only need values, not indices
        // ============================================================
        double total = 0;
        double maxDeposit = deposits[0];  // Initialize to first element — NOT to 0!
        double minDeposit = deposits[0];  // Same reason — what if all values are negative?

        for (double d : deposits) {
            total += d;
            if (d > maxDeposit) maxDeposit = d;
            if (d < minDeposit) minDeposit = d;
        }
        double average = total / deposits.length;

        System.out.printf("%n===== Aggregate Statistics =====%n");
        System.out.printf("Total deposits   : ₹%,.2f%n", total);
        System.out.printf("Average deposits : ₹%,.2f%n", average);
        System.out.printf("Highest deposit  : ₹%,.2f%n", maxDeposit);
        System.out.printf("Lowest deposit   : ₹%,.2f%n", minDeposit);

        // ============================================================
        // SECTION 4: Find Best and Worst Branch by Index
        // ============================================================
        int maxIdx = 0;
        int minIdx = 0;
        for (int i = 1; i < deposits.length; i++) {
            if (deposits[i] > deposits[maxIdx]) maxIdx = i;
            if (deposits[i] < deposits[minIdx]) minIdx = i;
        }
        System.out.printf("%n===== Top & Bottom Performers =====%n");
        System.out.printf("Best branch : %s (₹%,.2f)%n", branches[maxIdx], deposits[maxIdx]);
        System.out.printf("Worst branch: %s (₹%,.2f)%n", branches[minIdx], deposits[minIdx]);

        // ============================================================
        // SECTION 5: Arrays.sort() and Arrays.toString()
        // ============================================================
        // IMPORTANT: Don't sort the original array — we still need indices!
        double[] sortedDeposits = Arrays.copyOf(deposits, deposits.length);
        Arrays.sort(sortedDeposits);

        System.out.println("\n===== Sorted Deposits (Ascending) =====");
        System.out.println(Arrays.toString(sortedDeposits));
        // Without Arrays.toString(): System.out.println(sortedDeposits) → prints something like [D@6d06d69c
        // THAT is why Arrays.toString() exists!

        // ============================================================
        // SECTION 6: Above-Average Branches
        // ============================================================
        System.out.println("\n===== Above-Average Branches =====");
        System.out.printf("(Average: ₹%,.2f)%n", average);
        int countAboveAvg = 0;
        for (int i = 0; i < branches.length; i++) {
            if (deposits[i] > average) {
                System.out.printf("  %-12s : ₹%,.2f  (+%.1f%% above avg)%n",
                                  branches[i], deposits[i],
                                  ((deposits[i] - average) / average) * 100);
                countAboveAvg++;
            }
        }
        System.out.println("Branches above average: " + countAboveAvg + " of " + branches.length);

        // ============================================================
        // SECTION 7: Array Mutation — Annual Growth (10%)
        // Demonstrate: for-each CANNOT modify; index loop CAN
        // ============================================================
        System.out.println("\n===== After 10% Annual Growth =====");
        for (int i = 0; i < deposits.length; i++) {
            deposits[i] *= 1.10;  // 10% growth
        }
        // If you used for-each: for (double d : deposits) { d *= 1.10; }  → NO EFFECT on original!

        for (int i = 0; i < branches.length; i++) {
            System.out.printf("%-12s : ₹%,.2f%n", branches[i], deposits[i]);
        }

        // ============================================================
        // CHALLENGE: Varargs method for flexible totaling
        // ============================================================
        // TODO: Write a static method 'totalDeposits(double... amounts)' below main()
        // Then call it here:
        // System.out.printf("%nTop 3 branch total: ₹%,.2f%n",
        //     totalDeposits(deposits[1], deposits[4], deposits[5]));
    }

    // TODO: Implement this varargs method
    // public static double totalDeposits(double... amounts) {
    //     // Sum all amounts using enhanced for-each
    //     // Return the total
    // }
}

import java.util.Arrays;

public class BankStatementGenerator {

    // ========= Constants (best practice: named constants, not magic numbers) =========
    static final double OPENING_BALANCE     = 50_000.0;
    static final double MIN_BALANCE         = 1_000.0;
    static final double LARGE_TXN_THRESHOLD = 20_000.0;  // Flag transactions over this
    static final String ACCOUNT_NUMBER      = "ACC-9876543210";
    static final String CUSTOMER_NAME       = "Krishvi Achalla";
    static final String ACCOUNT_TYPE        = "Savings";

    public static void main(String[] args) {

        // ========= Transaction Data =========
        // Positive = Credit (money coming IN), Negative = Debit (money going OUT)
        double[] transactions = {
            +15_000,   // Salary credit
            -5_000,    // Electricity bill
            +25_000,   // FD maturity
            -12_000,   // Online shopping
            -3_500,    // Restaurant
            +50_000,   // Client payment
            -45_000,   // Rent payment
            -1_200,    // Mobile recharge
            +8_000,    // Interest credit
            -2_800,    // Grocery
        };

        String[] descriptions = {
            "SALARY-ROBOBANK-FEB", "BESCOM-ELECTRICITY", "FD-MATURITY-12345",
            "AMAZON-PURCHASE", "ZOMATO-FOOD", "CLIENT-PAYMENT-XYZ",
            "RENT-MARCH", "AIRTEL-RECHARGE", "SAVINGS-INT-FEB", "BIGBASKET"
        };

        // ========= Print Statement Header =========
        System.out.println("================================================");
        System.out.println("            RoboBank - Account Statement         ");
        System.out.println("================================================");
        System.out.printf("Customer  : %-30s%n", CUSTOMER_NAME);
        System.out.printf("Account   : %-30s%n", ACCOUNT_NUMBER);
        System.out.printf("Type      : %-30s%n", ACCOUNT_TYPE);
        System.out.printf("Opening   : ₹%,.2f%n", OPENING_BALANCE);
        System.out.println("------------------------------------------------");
        System.out.printf("%-4s %-24s %8s %12s%n", "#", "Description", "Amount", "Balance");
        System.out.println("------------------------------------------------");

        // ========= Process Transactions =========
        double runningBalance = OPENING_BALANCE;
        double totalCredit = 0;
        double totalDebit  = 0;
        int    creditCount = 0;
        int    debitCount  = 0;
        int    largeTxnCount = 0;

        for (int i = 0; i < transactions.length; i++) {
            double txnAmt = transactions[i];
            runningBalance += txnAmt;

            // Categorize
            if (txnAmt > 0) {
                totalCredit += txnAmt;
                creditCount++;
            } else {
                totalDebit += Math.abs(txnAmt);
                debitCount++;
            }

            // Flag large transactions
            boolean isLarge = Math.abs(txnAmt) >= LARGE_TXN_THRESHOLD;
            if (isLarge) largeTxnCount++;
            String flag = isLarge ? " ***" : "";

            // Print transaction row
            String amtStr = (txnAmt > 0 ? "+" : "") + String.format("₹%,.2f", txnAmt);
            System.out.printf("%-4d %-24s %12s  ₹%,.2f%s%n",
                              i + 1, descriptions[i], amtStr, runningBalance, flag);

            // Check minimum balance
            if (runningBalance < MIN_BALANCE) {
                System.out.println("   ⚠ WARNING: Balance below minimum (₹" + MIN_BALANCE + ")");
            }
        }

        // ========= Statement Footer =========
        System.out.println("------------------------------------------------");
        System.out.println("                  STATEMENT SUMMARY");
        System.out.println("------------------------------------------------");
        System.out.printf("Opening Balance  : ₹%,.2f%n", OPENING_BALANCE);
        System.out.printf("Total Credits    : ₹%,.2f (%d transactions)%n", totalCredit, creditCount);
        System.out.printf("Total Debits     : ₹%,.2f (%d transactions)%n", totalDebit, debitCount);
        System.out.printf("Closing Balance  : ₹%,.2f%n", runningBalance);
        System.out.printf("Large Txns (>₹%.0f) : %d%n", LARGE_TXN_THRESHOLD, largeTxnCount);
        System.out.println("------------------------------------------------");

        // Account health using ternary
        String health = (runningBalance >= 10_000) ? "GOOD" :
                        (runningBalance >= MIN_BALANCE) ? "LOW" : "CRITICAL";
        System.out.println("Account Health   : " + health);
        System.out.println("================================================");

        // ========= Sort and show top 3 transactions =========
        double[] absTxns = new double[transactions.length];
        for (int i = 0; i < transactions.length; i++) {
            absTxns[i] = Math.abs(transactions[i]);
        }
        double[] sortedAbs = Arrays.copyOf(absTxns, absTxns.length);
        Arrays.sort(sortedAbs);  // ascending

        System.out.println("\nTop 3 Largest Transactions:");
        for (int i = sortedAbs.length - 1; i >= sortedAbs.length - 3; i--) {
            System.out.printf("  ₹%,.2f%n", sortedAbs[i]);
        }
    }
}
